mapper.update:
UPDATE lab_equipment_reserve
equipment_id = #{equipmentId}, user_id = #{userId}, reserve_quantity = #{reserveQuantity}, reserve_date = #{reserveDate}, start_time = #{startTime}, end_time = #{endTime}, status = #{status}, original_status = #{originalStatus}, is_used = #{isUsed}, status_text = #{statusText}, purpose = #{purpose,jdbcType=VARCHAR}, update_time = NOW()
WHERE id = #{id}

mapper.select:
SELECT * FROM lab_equipment_reserve
WHERE 1=1
AND equipment_id = #{equipmentId}
AND user_id = #{userId}
AND create_time >= #{startTime}
AND create_time <= #{endTime}
ORDER BY create_time DESC
